  AgentBranding: 'AgentBranding',
  Property: 'Property',
  Tenancy: 'Tenancy',
  TenancyCollaborator: 'TenancyCollaborator',
  Inspection: 'Inspection',
  InspectionAccessGrant: 'InspectionAccessGrant',
  Capture: 'Capture',
